1	#!/usr/bin/env node
2	// Adoption interviews — the mandatory questions a pack asks when a project
3	// adopts it. A pack that needs the project's INTENT before it can provide value
4	// (barriers with no graph is a silent no-op) declares its questions in an
5	// optional `questions` field on its pack.mjs:
6	//
7	//   questions: [{ id: 'goals', prompt: '…', distill: '…' }]
8	//
9	// Stable-id'd, because the answers live VERBATIM on the pack's entry in
10	// .claudinite-settings.json (`answers: { "<question-id>": "<answer>" }` — see
11	// engine/checks/README.md): the settings file records the project's intent beside the
12	// `config` distilled from it. The GAP — declared question ids minus answered
13	// ids — drives the asking: at adoption every question is pending; when the
14	// canon later adds a question to a pack, just that one surfaces in every
15	// consumer; a pack with no questions adds nothing. An answered question stays
16	// answered — "n/a, none wanted" is an answer, distinct from never-asked.
17	//
18	//   node interview.mjs check   SessionStart step: when active packs have
19	//                              unanswered questions, emit a MILD context note
20	//                              asking the assistant to interview the owner at a
21	//                              natural moment — and telling an unattended
22	//                              session to ignore it entirely. Deliberately
23	//                              never a conformance finding: a nightly run must
24	//                              not be blocked on a question nobody is present
25	//                              to answer. Strictness lives only in the
26	//                              bootstrap adoption flow (bootstrap.md Part 2),
27	//                              where the owner is present by construction.
28	import { pathToFileURL } from 'node:url';
29	import { loadPacks, isActive, packQuestions } from '../../../../engine/pack_loader/pack-registry.mjs';
30	import { loadConfig } from '../../../../engine/checks/helpers/repo-context.mjs';
31	
32	// packQuestions (the `questions` manifest-shape validator) now lives with pack
33	// loading in the engine — re-exported here so this module's importers (the tests,
34	// the hygiene check) keep one path to it.
35	export { packQuestions };
36	
37	// The repo's interview state: for each ACTIVE pack, the declared questions its
38	// entry hasn't answered (`pending`) and the stored answers whose question the
39	// pack no longer declares (`stale` — renamed or removed upstream). `errors` is
40	// retained for callers that want it, but the ENGINE no longer reads it: a
41	// malformed `questions` declaration is now a load fault the pack registry
42	// reports (packQuestions runs at discovery), so the interview machinery never
43	// has to be imported by a core file to surface one. Pure — `config` is
44	// loadConfig's normalized shape. The two live consumers split the posture:
45	// `check` (below) surfaces pending as a mild SessionStart note and NEVER as a
46	// finding; the adopt-claudinite skill's hygiene check (checks.mjs) surfaces
47	// stale as an ADVISORY finding (visible, never run-failing — a canon-side
48	// question rename must not fail the fleet's CI overnight).
49	export function interviewState(packs, config) {
50	  const pending = [];
51	  const stale = [];
52	  const errors = [];
53	  const entryById = new Map((config.packEntries ?? []).map((e) => [e.id, e]));
54	  for (const pack of packs) {
55	    if (!isActive(pack, config)) continue;
56	    const entry = entryById.get(pack.id);
57	    // A dependency the declaration resolver materialized (`via`) wasn't chosen
58	    // by the project — it's there because another pack's ability rides it.
59	    // Until the project engages with it (its own config or answers on the
60	    // entry), its adoption questions don't apply: the interview guides a
61	    // CHOSEN adoption, and nagging every consumer whose baseline pulls a
62	    // mechanism pack in would train owners to ignore the note.
63	    if (entry?.via?.length && entry.config === undefined && !Object.keys(entry.answers ?? {}).length) continue;
64	    const { questions, errors: qErrors } = packQuestions(pack);
65	    errors.push(...qErrors);
66	    const answers = entry?.answers ?? {};
67	    const unanswered = questions.filter((q) => !(q.id in answers));
68	    if (unanswered.length) pending.push({ packId: pack.id, questions: unanswered });
69	    // With a malformed declaration the declared-id set is unreliable, so skip
70	    // stale detection for this pack — the blocking error already says what's wrong.
71	    if (qErrors.length) continue;
72	    const declaredIds = new Set(questions.map((q) => q.id));
73	    for (const id of Object.keys(answers)) {
74	      if (!declaredIds.has(id)) stale.push({ packId: pack.id, answerId: id });
75	    }
76	  }
77	  return { pending, stale, errors };
78	}
79	
80	// The SessionStart note for pending questions. Mild by design, and explicitly
81	// self-defusing for unattended sessions — the wording IS the guarantee that a
82	// nightly run is never derailed by it.
83	export function renderPending(pending) {
84	  const lines = [
85	    'Pack adoption interview pending — the active packs below declare adoption questions this '
86	    + 'project has not answered. In an INTERACTIVE session, at a natural moment (not mid-task), '
87	    + 'ask the owner each question via AskUserQuestion, record the answer VERBATIM in '
88	    + '.claudinite-settings.json on that pack\'s entry as answers: { "<question-id>": "<answer>" } '
89	    + '("n/a — none wanted" is a valid answer and stops the asking), and where the question '
90	    + 'carries a distill note, derive the entry\'s config from the answer. This is a mild '
91	    + 'reminder, never a gate: in an unattended session, or when it would derail the work at '
92	    + 'hand, ignore it entirely and leave it for a later interactive session.',
93	  ];
94	  for (const p of pending) {
95	    for (const q of p.questions) {
96	      lines.push(`- ${p.packId} / ${q.id}: ${q.prompt}${q.distill ? ` [distill: ${q.distill}]` : ''}`);
97	    }
98	  }
99	  return lines.join('\n');
100	}
101	
102	async function check(projectRoot) {
103	  const config = loadConfig(projectRoot);
104	  const packs = await loadPacks({ localRoot: projectRoot });
105	  const { pending } = interviewState(packs, config);
106	  if (pending.length) process.stdout.write(`${renderPending(pending)}\n`);
107	}
108	
109	// CLI — but importable (the tests and the runner import the pure helpers above).
